var a=`1177-aguachile`;var r=`world-1177`;var n=`MX`;var t=`central-america-caribbean`;var o=4;var l=53;var s={en:`Aguachile`,ua:`Агуачіле`};var h={en:`Aguachile is a dish from Mexico prepared with shrimp, lime juice, serrano pepper, cilantro. This is a home-scale version with measured ingredients in the individual steps where they are used. Fully cooked shrimp rather than raw aguachile; lime alone is not a reliable pathogen kill step.`,ua:`Агуачіле, страва кухні країни Мексика, яку готують із таких продуктів: креветка, сік лайма, перець серрано, кінза. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Повністю термічно приготовані креветки замість сирого агуачіле; лайм сам по собі не гарантує знищення патогенів.`};var c=[{en:`Poach the shrimp until fully opaque, rinse promptly with cold water, then chill. Lime juice alone does not make raw shrimp reliably safe.`,ua:`Варіть креветки до повної непрозорості, швидко охолодіть під холодною водою й поставте в холодильник. Лайм сам по собі не робить сирі креветки гарантовано безпечними.`,t:[`poaching`],m:8,i:[[`shrimp`,700,`g`],[`water`,650,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`lime-juice`,160,`ml`],[`serrano-pepper`,4,`pcs`],[`cilantro`,35,`g`],[`table-salt`,7,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:9,i:[[`cucumber`,280,`g`],[`red-onion`,170,`g`]]},{en:`Refrigerate the prepared mixture for about 25 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 25 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:25,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`avocado`,2,`pcs`]]}];var p={slug:a,id:r,country:`MX`,region:t,servings:4,minutes:53,title:s,text:h,steps:c};export{n as country,p as default,r as id,l as minutes,t as region,o as servings,a as slug,c as steps,h as text,s as title};